[CmdletBinding()]
param([switch]$ClipboardRelay)
# PREPARED ONLY. Run only when the coordinator requests fresh final owner input.
# PowerShell 5.1; no files/registry/storage writes, no SSH/browser sends.
# Optional -ClipboardRelay copies ONLY after the same proof is still on clipboard.
$ErrorActionPreference = 'Stop'
if ([Environment]::OSVersion.Platform -ne [PlatformID]::Win32NT -or $PSVersionTable.PSVersion.Major -lt 5) { throw 'WINDOWS_POWERSHELL_51_REQUIRED' }
$Utf8Strict = New-Object Text.UTF8Encoding($false,$true)
$Started = [DateTimeOffset]::UtcNow
function Digest([byte[]]$Bytes) {
  $H=[Security.Cryptography.SHA256]::Create()
  try { return (-join ($H.ComputeHash($Bytes) | ForEach-Object {$_.ToString('x2')})) } finally {$H.Dispose()}
}
function Keys($Value,[string[]]$Expected) {
  if ($Value -isnot [pscustomobject] -or ((@($Value.PSObject.Properties.Name | Sort-Object) -join ',') -cne (@($Expected | Sort-Object) -join ','))) {throw 'UNEXPECTED_JSON_FIELDS'}
}
function Decode([string]$Text,[int]$Size,[string]$Sha) {
  [byte[]]$Bytes=[Convert]::FromBase64String($Text)
  if ([Convert]::ToBase64String($Bytes) -cne $Text -or $Bytes.Length -ne $Size -or (Digest $Bytes) -cne $Sha) {throw 'ORIGINAL_BYTES_PIN_MISMATCH'}
  return ,$Bytes
}
function Fresh([string]$Text) {
  $At=[DateTimeOffset]::ParseExact($Text,"yyyy-MM-dd'T'HH:mm:ss.fff'Z'",[Globalization.CultureInfo]::InvariantCulture,[Globalization.DateTimeStyles]::AssumeUniversal)
  $Age=([DateTimeOffset]::UtcNow-$At).TotalMilliseconds
  if ($Age -lt -5000 -or $Age -gt 300000 -or $At -lt $Started) {throw 'POPUP_PROOF_NOT_CREATED_DURING_THIS_WAIT'}
}
$Pins=@'
[{"path":"manifest.json","bytes":1019,"sha256":"f3ff382a89cb1eba6a92351daf2d7e0d8b94df354ea586e356df5d58c66b944d"},{"path":"serviceWorker.js","bytes":189728,"sha256":"a673a75996f8c24d486861c8c8f94e916bb4b662bfb42d70dfe54d5cf351e607"},{"path":"contentScript.js","bytes":22461,"sha256":"18e6fa923fabf879b07785266b56a4ad9599f97ea2ca8c4137d9788f21f7b8a3"},{"path":"p01-startup.json","bytes":1095,"sha256":"fc4d970903a94d6c49fc6dd5a9edf6f4aec4a61ccbfaf8c149974b203d2649d5"},{"path":"setup.html","bytes":472,"sha256":"0fa73cf5f0d057f676746ef3191bfffc31632419bb1d004b444765a722201b69"},{"path":"setup.js","bytes":16855,"sha256":"cd62b10d92c02292f64f99fd919cee60086b4de1397fad3debb7aad34d447028"}]
'@ | ConvertFrom-Json
$Scope=@'
{"appId":"cocwin","baseSha":"2f17ffcf5d8aefbb7bd3d3e4506f8fee965fd6db","sessionId":"exta-4786c8bd94d2feecc1e26a031b0693d6","generation":"7e7d5e17-2c44-4094-a6c8-0cf470ed564c"}
'@ | ConvertFrom-Json
function Scope-Equal($S) {
  Keys $S @('appId','baseSha','sessionId','generation')
  foreach($K in @('appId','baseSha','sessionId','generation')) {if($S.$K -cne $Scope.$K){throw 'ORIGINAL_SCOPE_MISMATCH'}}
}
function Validate-Proof($P) {
  Keys $P @('schema','status','independentlyAuthenticated','createdAt','extensionId','runtimeManifest','target','resources','storedStartup','browserSends','storageWrites')
  if ($P.schema -cne 'COCWIN_P01_OWNER_INSTALLED_EXTENSION_PROOF_V1' -or $P.status -cne 'LOCAL_OWNER_OBSERVATION' -or $P.independentlyAuthenticated -isnot [bool] -or $P.independentlyAuthenticated -ne $false -or $P.extensionId -cne 'ebibbijpegoankenmggdnehpoadcophk' -or $P.browserSends -ne 0 -or $P.storageWrites -ne 0 -or @($P.resources).Count -ne 6) {throw 'POPUP_PROOF_INVALID'}
  Fresh $P.createdAt
  for($I=0;$I -lt 6;$I++) {
    $R=$P.resources[$I];$Pin=$Pins[$I];Keys $R @('path','bytes','sha256','base64')
    if($R.path -cne $Pin.path -or $R.bytes -ne $Pin.bytes -or $R.sha256 -cne $Pin.sha256){throw 'EXTENSION_RESOURCE_PIN_MISMATCH'}
    [byte[]]$B=Decode $R.base64 $Pin.bytes $Pin.sha256
    if($R.path -ceq 'p01-startup.json'){$Startup=$Utf8Strict.GetString($B)|ConvertFrom-Json}
  }
  Keys $P.storedStartup @('state','bytes','sha256','base64')
  if($P.storedStartup.state -cne 'PRESENT'){throw 'STORED_STARTUP_ABSENT'}
  [byte[]]$Stored=Decode $P.storedStartup.base64 1095 'fc4d970903a94d6c49fc6dd5a9edf6f4aec4a61ccbfaf8c149974b203d2649d5'
  Scope-Equal $Startup.scope
  if($Startup.schema -cne 'RBRIDGE_EXTENSION_STARTUP_V3' -or $Startup.siteAdapter -cne 'CHATGPT_EXACT_COPY_V3' -or $Startup.releaseSha -cne '931e02d6b771a351e8c4e4977cf25ebf82d12a13') {throw 'STARTUP_BINDING_MISMATCH'}
  $T=$P.target
  if($T.schema -cne 'COCWIN_P01_OWNER_ACTIVE_TAB_OBSERVATION_V1' -or $T.status -cne 'OBSERVED_NOT_BOUND' -or $T.scopeSessionId -cne $Scope.sessionId -or $T.browserInstanceId -cne 'chrome-p01-02863497258502a5c41b' -or $T.browserProfileId -cne 'profile-p01-85f1cf34e7941c55089a' -or $T.origin -cne 'https://chatgpt.com') {throw 'POPUP_TARGET_SCOPE_MISMATCH'}
}
# The command must already be waiting before the owner clicks the popup export.
# Unrecognized clipboard values are never printed/exported/logged or parsed.
[Console]::Error.WriteLine('WAITING (120 seconds): in the intended Canary ChatGPT tab, click RBridge > Kopiraj V3 instalaciju. Do not click Activate/Setup.')
$Deadline=[DateTimeOffset]::UtcNow.AddSeconds(120)
$ProofText=$null
while([DateTimeOffset]::UtcNow -lt $Deadline) {
  $Candidate=Get-Clipboard -Raw -ErrorAction SilentlyContinue
  if($Candidate -is [string] -and $Candidate.Length -le 1500000 -and $Candidate -cmatch '"schema"\s*:\s*"COCWIN_P01_OWNER_INSTALLED_EXTENSION_PROOF_V1"') {
    $Proof=$Candidate|ConvertFrom-Json -ErrorAction Stop
    # A recognized old clipboard proof is ignored while waiting for the new click.
    try { Fresh $Proof.createdAt } catch { $Candidate=$null; Start-Sleep -Milliseconds 500; continue }
    Validate-Proof $Proof
    $ProofText=$Candidate;$Candidate=$null;break
  }
  $Candidate=$null
  Start-Sleep -Milliseconds 500
}
if($null -eq $ProofText){throw 'NO_FRESH_RECOGNIZED_POPUP_PROOF_WITHIN_120_SECONDS'}
# Exact previously qualified 931e collector, with ONLY the already used Canary path correction.
$CollectorBase64=''
[byte[]]$CollectorBytes=[Convert]::FromBase64String($CollectorBase64)
if($CollectorBytes.Length -ne 17579 -or (Digest $CollectorBytes) -cne '832e3ef5e690c444b466bcfe37fa1f8ecce43c5d536de6e346c3dfb0160d78b7') {throw 'PINNED_COLLECTOR_CHANGED'}
# Dot-source once in memory; retain its original no-reparse / read-sharing helpers.
$FactsOutput=@(. ([ScriptBlock]::Create($Utf8Strict.GetString($CollectorBytes))))
if($FactsOutput.Count -ne 1 -or $FactsOutput[0] -isnot [string]){throw 'FACTS_COLLECTOR_OUTPUT_INVALID'}
$FactsText=$FactsOutput[0];$Facts=$FactsText|ConvertFrom-Json
if($Facts.schema -cne 'COCWIN_RBRIDGE_WINDOWS_OWNER_FACTS_V1' -or $Facts.status -cne 'COLLECTED_READONLY' -or $Facts.filesystemChanges -ne 0 -or $Facts.sshConnections -ne 0 -or $Facts.browserSends -ne 0){throw 'FACTS_COLLECTOR_NOT_READONLY'}
$NativeDir=Local-Path (Join-Path $env:LOCALAPPDATA 'COCWIN\RBridge\NativeHost')
# Observe-File uses original CreateFileW READ access, Share.Read only, no reparse,
# held local-volume ancestor handles and Nlink1. No write/delete-sharing allowed.
$ConfigRead=Observe-File (Join-Path $NativeDir 'rbridge-native-host.config.json') 65536 $true
$ManifestRead=Observe-File (Join-Path $NativeDir 'com.cocwin.rbridge_chat_v1.json') 16384 $true
if($ConfigRead.state -cne 'PRESENT_METADATA_ONLY' -or $ConfigRead.bytes -ne 1553 -or $ConfigRead.sha256 -cne '648e5d88a3eb3a98dd0c7c2508a7071eeaf642176b3587f5ecd22f4d43e0a70a' -or $ManifestRead.state -cne 'PRESENT_METADATA_ONLY' -or $ManifestRead.bytes -ne 372 -or $ManifestRead.sha256 -cne '537717d92a24d8cf696e7b506fbdaeb745cbbc6627f16566e346e7c7056424a3'){throw 'INSTALLED_NATIVE_ORIGINALS_CHANGED_STOP_NO_REPAIR'}
$Cfg=$Utf8Strict.GetString($ConfigRead.rawBytes)|ConvertFrom-Json
$Allowed=@('schema','expectedExtensionId','eventStoreRoot','ssh','v3')
foreach($Optional in @('maxEvents','maxEventBytes')){if(@($Cfg.PSObject.Properties.Name) -contains $Optional){$Allowed+=@($Optional)}}
Keys $Cfg $Allowed;Keys $Cfg.ssh @('sshPath','host','port','user','identityFile','knownHostsFile');Keys $Cfg.v3 @('scope','peerPins','initialHistory')
Scope-Equal $Cfg.v3.scope
if($Cfg.schema -cne 'RBRIDGE_NATIVE_HOST_CONFIG_V1' -or $Cfg.expectedExtensionId -cne 'ebibbijpegoankenmggdnehpoadcophk' -or $Cfg.ssh.user -cne 'rbridge'){throw 'NATIVE_CONFIG_NOT_PUBLIC_EXPECTED_GRAMMAR'}
foreach($Name in @('sshPath','host','identityFile','knownHostsFile','eventStoreRoot')) {
  $Value=if($Name -ceq 'eventStoreRoot'){$Cfg.eventStoreRoot}else{$Cfg.ssh.$Name}
  if($Value -isnot [string] -or $Value.Length -gt 1024 -or $Value -match '[\r\n\x00]' -or $Value -match '(?i)(BEGIN .*PRIVATE KEY|password\s*[:=]|token\s*[:=]|secret\s*[:=])'){throw 'NATIVE_CONFIG_NONPUBLIC_VALUE_REJECTED'}
}
$NativeManifest=$Utf8Strict.GetString($ManifestRead.rawBytes)|ConvertFrom-Json
Keys $NativeManifest @('name','description','path','type','allowed_origins')
if($NativeManifest.name -cne 'com.cocwin.rbridge_chat_v1' -or $NativeManifest.type -cne 'stdio' -or @($NativeManifest.allowed_origins).Count -ne 1 -or $NativeManifest.allowed_origins[0] -cne 'chrome-extension://ebibbijpegoankenmggdnehpoadcophk/'){throw 'NATIVE_MANIFEST_ORIGIN_MISMATCH'}
if($Facts.installation.config.sha256 -cne $ConfigRead.sha256 -or $Facts.installation.manifest.sha256 -cne $ManifestRead.sha256 -or $Facts.installation.executable.bytes -ne 87200256 -or $Facts.installation.executable.sha256 -cne 'c4d9317d84dbd7ac2f0d73df3c939fe2452eb6a78e56a142d17c83876228e5ee'){throw 'FACTS_VS_ORIGINAL_BYTES_MISMATCH'}
Fresh $Proof.createdAt
$Sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value
if($Sid -cnotmatch '^S-1-[0-9-]{3,180}$'){throw 'WINDOWS_OWNER_SID_UNAVAILABLE'}
$ObservedAt=[DateTimeOffset]::UtcNow.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'",[Globalization.CultureInfo]::InvariantCulture)
[byte[]]$FactsBytes=$Utf8Strict.GetBytes($FactsText)
[byte[]]$ProofBytes=$Utf8Strict.GetBytes($ProofText)
# LOCAL observation only. Trusted acquisition must authenticate origin separately.
$Original=@{observer=@{kind='WINDOWS_OWNER';sid=$Sid;processId=$PID};observedAt=$ObservedAt;
 factsBase64=[Convert]::ToBase64String($FactsBytes);nativeConfigBase64=[Convert]::ToBase64String($ConfigRead.rawBytes);nativeManifestBase64=[Convert]::ToBase64String($ManifestRead.rawBytes);extensionProofBase64=[Convert]::ToBase64String($ProofBytes)}
$Result=[pscustomobject]@{schema='COCWIN_P01_WINDOWS_ORIGINALS_BUNDLE_V1';status='LOCAL_OWNER_OBSERVATION';independentlyAuthenticated=$false;
 windowsOriginal=$Original;startedAt=$Started.ToString("yyyy-MM-dd'T'HH:mm:ss.fff'Z'",[Globalization.CultureInfo]::InvariantCulture);
 digests=@{facts=@{bytes=$FactsBytes.Length;sha256=(Digest $FactsBytes)};nativeConfig=@{bytes=$ConfigRead.bytes;sha256=$ConfigRead.sha256};nativeManifest=@{bytes=$ManifestRead.bytes;sha256=$ManifestRead.sha256};extensionProof=@{bytes=$ProofBytes.Length;sha256=(Digest $ProofBytes)}};
 collectorSha256='832e3ef5e690c444b466bcfe37fa1f8ecce43c5d536de6e346c3dfb0160d78b7';filesystemChanges=0;registryChanges=0;storageWrites=0;clipboardWrites=0;clipboardRelay='NOT_REQUESTED';sshConnections=0;browserSends=0}
# Optional task-specific output handoff; unrelated/new clipboard content is never
# exported or replaced. Recheck exact original proof immediately before one set.
if($ClipboardRelay) {
  $SetCommand=Get-Command Set-Clipboard -CommandType Cmdlet -ErrorAction SilentlyContinue
  if($null -eq $SetCommand) {$Result.clipboardRelay='UNAVAILABLE_TERMINAL_ONLY'}
  else {
    $Current=Get-Clipboard -Raw -ErrorAction SilentlyContinue
    $SameProof=$Current -is [string] -and $Current.Length -eq $ProofText.Length -and (Digest ($Utf8Strict.GetBytes($Current))) -ceq (Digest $ProofBytes)
    $Current=$null
    if(-not $SameProof) {$Result.clipboardRelay='CHANGED_TERMINAL_ONLY'}
    else {
      $Result.clipboardWrites=1;$Result.clipboardRelay='COPIED'
      $RelayJson=$Result|ConvertTo-Json -Depth 12 -Compress
      try {Set-Clipboard -Value $RelayJson -ErrorAction Stop}
      catch {
        # A failed setter may have changed the clipboard: do not falsely claim0.
        $Result.clipboardWrites='UNKNOWN';$Result.clipboardRelay='SET_FAILED_UNCERTAIN_TERMINAL_ONLY'
      }
    }
  }
}
$Result | ConvertTo-Json -Depth 12 -Compress
